export function renderInviteEmail(vars: InviteEmailVars): RenderedEmail {
  const t = renderInviteEmailTemplates['default']!
  const values = [vars.inviterName, vars.householdName, vars.inviteUrl, vars.email, vars.expiresOn]
  return {
    subject: fill(t.subject, values, oneLine),
    html: fill(t.html, values, escapeHtml),
    text: fill(t.text, values, identity),
  }
}

