export function renderTaskReminderEmail(variant: TaskReminderEmailVariant, vars: TaskReminderEmailVars): RenderedEmail {
  const t = renderTaskReminderEmailTemplates[variant]!
  const values = [vars.recipientName, vars.taskTitle, vars.householdName, vars.dueDate, vars.dueText, vars.taskUrl, vars.providerLine, vars.reason]
  return {
    subject: fill(t.subject, values, oneLine),
    html: fill(t.html, values, escapeHtml),
    text: fill(t.text, values, identity),
  }
}
